package dev.alex.fyt.probe.tests;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import dev.alex.fyt.probe.*;import java.util.*;
/** Real player controls and compact climate overlay geometry; no vehicle commands. */
public final class PlayerClimateSpaceTests extends Instrumentation {
 private final ProbeState state=ProbeState.INSTANCE;private Activity activity;private ClimateStripOverlay strip;private ClimateOverlay popup;private int checks;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private Object field(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
 private Rect rect(View view){int[] xy=new int[2];runOnMainSync(()->view.getLocationOnScreen(xy));return new Rect(xy[0],xy[1],xy[0]+view.getWidth(),xy[1]+view.getHeight());}
 private void frame(int type,int... p){int[] a=new int[p.length+4];a[0]=46;a[1]=type;a[2]=p.length;int sum=type+p.length;for(int i=0;i<p.length;i++){a[i+3]=p[i];sum+=p[i];}a[a.length-1]=255-(sum&255);state.event(1019,a,null,null);}
 private void setup(int mode,boolean selected){state.newSession();state.running(true);state.status("test","local source and climate",true);state.event(1000,new int[]{6291908},null,null);state.event(98,new int[]{selected?(mode==0?1:mode==1||mode==3?2:4):1},null,null);if(mode==3)frame(6,50,34,34);int[] codes={21,27,28,11,19,13},values={4,44,46,1,1,1};for(int i=0;i<codes.length;i++)state.event(codes[i],new int[]{values[i]},null,null);if(mode==0){state.event(115,new int[]{1},null,null);state.event(119,new int[]{241},null,null);}}
 private void stop(){if(strip!=null)runOnMainSync(()->strip.close());if(popup!=null)runOnMainSync(()->popup.close());strip=null;popup=null;if(activity!=null)runOnMainSync(()->activity.finish());waitForIdleSync();activity=null;SystemClock.sleep(200);}
 private void image(Context c,String name)throws Exception{SystemClock.sleep(350);Bitmap b=getUiAutomation().takeScreenshot();try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void verify(boolean selected)throws Exception{
  ViewGroup empty=activity.findViewById(android.R.id.content).findViewWithTag("player-climate-space");TextView select=(TextView)field(activity,"select");Button prev=(Button)field(activity,"previous"),next=(Button)field(activity,"next");Rect reserved=rect(empty),compact=rect((View)field(strip,"strip")),source=rect(select),previous=rect(prev),following=rect(next);
  float density=activity.getResources().getDisplayMetrics().density;int screen=activity.getResources().getDisplayMetrics().widthPixels;
  check(empty.getChildCount()==0&&!empty.isClickable()&&!empty.isFocusable(),"empty spacer has no controls");
  check(!Rect.intersects(compact,source)&&!Rect.intersects(compact,previous)&&!Rect.intersects(compact,following),"compact climate content does not cover player buttons");
  check(reserved.left<=compact.left&&reserved.right>=compact.right,"empty space contains compact climate content");
  check(select.getWidth()==Math.round(300*density),"source label stays compact");check(select.getBackground()==null&&select.getCompoundDrawablesRelative()[0]!=null,"source label has a status dot and no surface");
  check(prev.getWidth()==Math.round(160*density)&&next.getWidth()==Math.round(160*density),"transport controls narrowed to 160dp");
  check(following.right==screen-Math.round(28*density)&&following.left-previous.right==Math.round(10*density),"transport controls stay right aligned");
  check(source.top==previous.top&&previous.top==following.top&&select.getHeight()==Math.round(48*density),"all controls use the shorter 48dp bottom row");
  if(!selected){check(select.getText().toString().contains(I18n.t(R.string.player_vehicle_controls)),"full vehicle control note retained");check(select.getLayout()!=null&&select.getLayout().getLineCount()<=2,"source note fits two lines");}else check(!select.getText().toString().contains(I18n.t(R.string.player_vehicle_controls)),"selected source keeps short label");
 }
 @Override public void onStart(){Context c=getTargetContext();String theme=ThemeSettings.mode(c),lang=I18n.language(c);SharedPreferences prefs=c.getSharedPreferences("overlay",0);Map<String,?> old=prefs.getAll();String[] keys={"climateStrip","climateStripExpandButton","climateStripButtonAutoHide","climateStripAlwaysAutoHide","climateStripCollapsed","climate"};Bundle result=new Bundle();int outcome=Activity.RESULT_OK;
  try{c.stopService(new Intent(c,ProbeService.class));SystemClock.sleep(300);ClimateStripOverlay.enabled(c,true);ClimateStripOverlay.expandButton(c,true);ClimateStripOverlay.buttonAutoHide(c,false);ClimateStripOverlay.alwaysAutoHide(c,false);ClimateOverlay.enabled(c,false);
   for(String appearance:new String[]{ThemeSettings.DAY,ThemeSettings.NIGHT})for(String language:new String[]{"en","ru"})for(int mode=0;mode<4;mode++){
    ThemeSettings.mode(c,appearance);I18n.language(c,language);prefs.edit().putBoolean("climateStripCollapsed",false).commit();setup(mode,true);activity=startActivitySync(AudioPlayerActivity.intent(c,mode==0?AudioMode.RADIO:mode==1?AudioMode.CD:AudioMode.USB,false));runOnMainSync(()->{popup=new ClimateOverlay(c);popup.start();strip=new ClimateStripOverlay(c,popup);strip.start();strip.refreshOptions();});SystemClock.sleep(650);verify(true);if(mode==1&&language.equals("ru"))image(c,"player-climate-space-"+appearance+"-TEST.png");stop();
   }
   I18n.language(c,"ru");ThemeSettings.mode(c,ThemeSettings.DAY);prefs.edit().putBoolean("climateStripCollapsed",false).commit();setup(1,false);activity=startActivitySync(AudioPlayerActivity.intent(c,AudioMode.CD,false));runOnMainSync(()->{popup=new ClimateOverlay(c);popup.start();strip=new ClimateStripOverlay(c,popup);strip.start();strip.refreshOptions();});SystemClock.sleep(650);verify(false);image(c,"player-climate-space-unselected-TEST.png");runOnMainSync(()->{try{((View)field(strip,"strip")).performClick();}catch(Exception e){throw new RuntimeException(e);}});SystemClock.sleep(450);View empty=activity.findViewById(android.R.id.content).findViewWithTag("player-climate-space");Rect handle=rect((View)field(strip,"view"));check(state.overlaySnapshot().climateStripCollapsed&&rect(empty).left<=handle.left&&rect(empty).right>=handle.right,"folded handle stays in reserved space");check(!state.snapshot().commandBusy,"layout and climate folding send no command");result.putString("result","PASS: "+checks+" actual player/compact-climate layout checks");
  }catch(Throwable e){outcome=1;result.putString("failure",android.util.Log.getStackTraceString(e));}finally{stop();state.newSession();state.running(false);ThemeSettings.mode(c,theme);I18n.language(c,lang);SharedPreferences.Editor edit=prefs.edit();for(String key:keys){Object value=old.get(key);if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else edit.remove(key);}edit.commit();}finish(outcome,result);
 }
}
